<template><main class="video-detail"><a-spin :spinning="loading"><a-alert v-if="error" type="error" :message="error" show-icon/><template v-if="record"><router-link to="/?media=video">← 视频图库</router-link><h1>{{record.name}}</h1><video class="player" :src="`${videoBase}/videos/${record.id}/media`" :poster="`${videoBase}/videos/${record.id}/media?kind=poster`" controls preload="metadata"/><div class="details"><span>{{frameTime(record.metadata.frames,record.metadata.fps)}} · {{record.metadata.width}} × {{record.metadata.height}} · 项目 v{{record.revision}}</span><a-space><a-button :href="`${videoBase}/videos/${record.id}/media?download=1`">下载 MP4</a-button><a-button type="primary" @click="router.push(`/video/editor/${record.project_id}`)">继续编辑</a-button><a-button v-if="admin&&record.review_status!==1" @click="review(1)">审核通过</a-button><a-button v-if="admin&&record.review_status!==2" danger @click="review(2)">审核拒绝</a-button></a-space></div></template></a-spin></main></template>
<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useLoginUserStore} from '@/stores/useLoginUserStore';import {videoApi,videoBase,frameTime,type VideoRecord} from '@/api/videoEditor'
const route=useRoute(),router=useRouter(),record=ref<VideoRecord>(),loading=ref(true),error=ref(''),store=useLoginUserStore(),admin=computed(()=>store.loginUser.userRole==='admin')
async function load(){try{record.value=await videoApi(`/videos/${route.params.id}`)}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function review(status:number){try{await videoApi(`/videos/${record.value!.id}/review`,{reviewStatus:status});await load()}catch(e){error.value=(e as Error).message}}
onMounted(load)
</script>
<style scoped>.video-detail{max-width:1100px;margin:20px auto;padding:12px}.player{width:100%;max-height:60vh;background:#080b10;border-radius:12px}.details{display:flex;justify-content:space-between;align-items:center;margin-top:20px;gap:12px;flex-wrap:wrap}.details span{color:#77808f}</style>
